    }
    var show = "设置成功\n当前模式：";
    var tips = "";
    var msg = show + data[num][0] + tips;
    java.longToast(msg);
    var setData = {
        sz: num.toString(),
        tone: data[num][1]
    };
    source.setVariable(JSON.stringify(setData));
}

// 获取接口显示
