ruleToc.chapterList:
@js:
lw = org.jsoup.Jsoup.parse(result).select("[class~=play_list_asc]");
le=lw.size();
n = 0; // 默认选择线路
v = String(book.getVariable("custom"));
x = v.match(/^\d+$/) ? v : n;
x = parseInt(x) < le ? x : n;
list=lw.get(x).select('button');
list;

