@js:
var url = source.key,
html = java.ajax(url);
a = org.jsoup.Jsoup.parse(html)
.select(".nav li:gt(0):lt(11) a");
var arr = [], sort = [];
if(html && a){
	arr = Array.from(a, x => {
		txt = x.text(),href = String(x.attr("href"));
		url = /_1/.test(href) ? href
		.replace(/_1/,"_{{page}}") : 
		href.replace(/1/, "{{page}}");
		if(!/1|html?$/g.test(url) ) url += "<,{{page}}.html>";
			return [txt, url] });
		sort = arr.map(([title, link]) => ({
    "title": title,
    "url": link,
    "style": {
      "layout_flexGrow": 1,
       "layout_flexBasisPercent": 0.2
    }
  }) );

  JSON.stringify(sort);

	}else java.toast("发现列表获取失败！");

@js:
var result = [];
java.toast("🔥正在刷新列表,请稍等！");
var push = (title, url, size) => result.push({
    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
    }
});
var baseUrl = "https://m.blpopo.com/xclass/0/1.html";
var tag = java.ajax(baseUrl);
if (tag) {
    var a = org.jsoup.Jsoup.parse(tag).select("nav a");
    push("🔥分类小说🔥", null, 1);
    for (var i = 0; i < a.length ; i++) {
        var title = a[i].text();
        var url = a[i].attr("href");
        var size = 0.25;
        title = String(title).replace(/\s/g, "");
        url = String(url).replace(/1\./,'{{page}}.');      
        push(title, url, size);
    }
} else {
  java.toast("🤔列表刷新失败！！！");     
} 
JSON.stringify(result);

